// Topic Selection stage -- a small, hand-curated array for THIS run, never
// "all topics" (same explicit-batch philosophy as scripts/export_approved_questions.py,
// Faz 143). Every run generates BOTH EN and TR independently (each grounded in its own
// real content/{lang}/{slug}.md, per the originally approved design -- never a
// translation pass). Edit topicSlug (and optionally add onlyLanguage/overrideCount for
// a scoped top-up run) here before each real run.
//
// This run's target: java/java-basics -> String (topic slug "string") -- a SCOPED
// TR-only top-up run, replacing the 3 TR questions the fixed AI Judge rejected (ids
// 337, 340, 341) without touching those rows themselves (they stay PENDING_REVIEW for
// auditability). onlyLanguage narrows Load Topic Content/Build Generation Spec to just
// TR; overrideCount=6 gives the model margin against the now-dense existing-question
// pool (44 rows) triggering normal dedup/validation skips, same pattern observed on
// the EN top-up run just before this one.
return [
  { json: { topicSlug: "string", onlyLanguage: "tr", overrideCount: 6 } }
];

// Load Topic Content stage -- calls the 3 new read-only /api/internal/** endpoints
// (topic metadata + EN content + TR content) for each selected topic. Uses the Code
// node's own HTTP helper so the whole "fetch + merge into one item" step stays in a
// single, easy-to-audit stage instead of 3 separate HTTP Request nodes + a Merge node.
const baseUrl = $env.QUESTION_INGEST_BASE_URL || "http://localhost:8080";
const apiKey = $env.QUIZ_INGEST_API_KEY;
const results = [];

for (const item of $input.all()) {
  const topicSlug = item.json.topicSlug;

  const metadata = await this.helpers.httpRequest({
    method: "GET",
    url: `${baseUrl}/api/internal/topics/${topicSlug}`,
    headers: { "X-Api-Key": apiKey },
    json: true,
  });

  const contentEn = await this.helpers.httpRequest({
    method: "GET",
    url: `${baseUrl}/api/internal/topics/${topicSlug}/content?lang=en`,
    headers: { "X-Api-Key": apiKey },
  });

  const contentTr = await this.helpers.httpRequest({
    method: "GET",
    url: `${baseUrl}/api/internal/topics/${topicSlug}/content?lang=tr`,
    headers: { "X-Api-Key": apiKey },
  });

  results.push({
    json: {
      topicSlug,
      onlyLanguage: item.json.onlyLanguage,
      overrideCount: item.json.overrideCount,
      difficulty: metadata.difficulty,
      categorySlug: metadata.categorySlug,
      courseSlug: metadata.courseSlug,
      contentEn: String(contentEn),
      contentTr: String(contentTr),
    }
  });
}
return results;

// Build Generation Spec stage -- deterministic, NO LLM call here. Parses the topic's
// own H2 outline (per this project's content convention, CLAUDE.md "Icerik Yazim
// Formati") as conceptual scope ONLY -- per the user's approved clarification, the
// outline is NOT used later as a literal keyword-match gate; content-fit is ensured by
// grounding the actual LLM prompt in the real lesson excerpt (see the prompt built
// below), not by post-hoc heading-vocabulary checking. Reuses Faz 7's content-depth
// bucket methodology (wc -l -> question count) and code-heaviness -> type-mix rule
// from the approved design.
function extractHeadings(md) {
  return md.split("\n")
    .filter(l => l.trim().startsWith("## "))
    .map(l => l.trim().replace(/^##\s+/, ""));
}

function countCodeSignals(md) {
  const embeds = (md.match(/\{\{[^}]+\}\}/g) || []).length;
  const fences = (md.match(/```/g) || []).length / 2;
  return embeds + fences;
}

function bucketForLineCount(lineCount) {
  if (lineCount < 150) return { bucket: "small", count: 5 };
  if (lineCount < 300) return { bucket: "normal", count: 7 };
  return { bucket: "detailed", count: 9 };
}

function typeMixFor(codeSignals) {
  if (codeSignals >= 8) {
    return { SINGLE_CHOICE: 0.55, CODE_OUTPUT: 0.35, MULTIPLE_CHOICE: 0.10 };
  }
  return { SINGLE_CHOICE: 0.70, MULTIPLE_CHOICE: 0.20, CODE_OUTPUT: 0.10 };
}

function difficultyDistributionFor(baseline) {
  if (baseline === "BEGINNER") return { BEGINNER: 0.6, INTERMEDIATE: 0.4, ADVANCED: 0.0 };
  if (baseline === "ADVANCED") return { BEGINNER: 0.0, INTERMEDIATE: 0.4, ADVANCED: 0.6 };
  return { BEGINNER: 0.25, INTERMEDIATE: 0.55, ADVANCED: 0.20 };
}

function buildPrompt(topicSlug, language, content, outlineHeadings, targetCount, typeMix, difficultyDistribution) {
  const langName = language === "tr" ? "Turkish" : "English";
  const typeMixStr = Object.entries(typeMix).map(([k, v]) => `${k}: ~${Math.round(v * 100)}%`).join(", ");
  const diffStr = Object.entries(difficultyDistribution).map(([k, v]) => `${k}: ~${Math.round(v * 100)}%`).join(", ");

  return `You are generating quiz questions for a software-engineering learning platform, topic "${topicSlug}". This topic may be about a programming language (e.g. Java) or a tool/workflow (e.g. Git) -- ground every question strictly in the lesson content below, whichever domain it covers.

The full lesson content for this topic (in ${langName}) is below. This is the ONLY source of truth -- every question and its explanation must be fully supported by this content. Do not introduce facts, APIs, or behavior not present here. The section outline below defines the topic's conceptual SCOPE only -- do not require literal vocabulary overlap with a heading; ground each question in the actual lesson text instead.

Topic outline (scope reference only):
${outlineHeadings.map(h => "- " + h).join("\n")}

--- LESSON CONTENT (${langName}) ---
${content}
--- END LESSON CONTENT ---

Generate exactly ${targetCount} quiz questions in ${langName}. Requirements:

- Approximate type mix: ${typeMixStr} (use judgment; skip a type that does not fit naturally).
- Approximate difficulty mix: ${diffStr}.
- Each question must have exactly 4 options.
- SINGLE_CHOICE and CODE_OUTPUT questions must have EXACTLY ONE correct option.
- MULTIPLE_CHOICE questions must have ONE OR MORE correct options.
- Ground every question strictly in the lesson content above -- never introduce a fact, API, or behavior that is not stated or directly implied there.

TEST UNDERSTANDING, NOT RECALL. At most ONE question in this batch may be a plain "What is X?" / "What does X mean?" definition question. All other questions must test one of: predicting the output of code, choosing the correct API/method for a scenario, distinguishing between two similar-looking concepts or methods (e.g. two methods that look interchangeable but behave differently), reasoning about a concrete usage scenario, or identifying a consequence/pitfall described in the lesson. A definition question is only acceptable when the topic has no behavior, API, or scenario left in the content to test -- prefer application over definition whenever the content supports it.

DISTRACTORS must be plausible, not absurd. Each wrong option should reflect a real misconception a learner could actually hold (a similar-sounding method, a common off-by-one/ordering mistake, confusing two related concepts from the lesson, etc.) -- never an option so obviously wrong that no reasoning is required to eliminate it.

EXPLANATIONS must do more than restate the correct option. State why the correct answer is right AND briefly address why the most plausible wrong option is wrong (not all distractors need coverage, just enough to show the reasoning, not just the conclusion).

AVOID REPETITIVE PATTERNS. Do not phrase multiple questions in this batch the same way (e.g. do not open several questions with "Which of the following..."). Vary sentence structure and the angle of each question.

CODE_OUTPUT questions: put the code ONLY in the "codeSnippet" field -- either valid, self-contained source code (e.g. Java) with fully deterministic output, OR a realistic terminal transcript (e.g. a sequence of git commands and the exact output they produce), whichever fits this topic's actual subject matter. Never force a Java code example onto a topic that is not about Java. The "question" field must be plain prose (e.g. "What will be the output of the following code?" or "What will this sequence of commands print?") and must NEVER itself contain the code/commands or any \`\`\` fenced block -- the snippet is rendered separately from codeSnippet, repeating it in the question text is a duplicate.

Return ONLY a JSON array (no prose, no markdown fences) where each element has exactly this shape:
{"type": "SINGLE_CHOICE" | "MULTIPLE_CHOICE" | "CODE_OUTPUT", "difficulty": "BEGINNER" | "INTERMEDIATE" | "ADVANCED", "question": "...", "codeSnippet": null or "...", "codeLanguage": null or "java" or "bash", "explanation": "...", "options": [{"optionText": "...", "correct": true|false}, ...]}

STRICT JSON ONLY: every string value must be valid JSON -- use only double quotes for the JSON string delimiters themselves. Do NOT use backtick characters (\`) anywhere inside a JSON string value to mark inline code (e.g. write "the equals() method", not "the \`equals()\` method") -- a backtick is not a JSON escape and will break parsing. If you need to reference a method/class name inside question/explanation/option text, write it as plain text with no special wrapping characters at all.`;
}

const results = [];
for (const item of $input.all()) {
  const { topicSlug, difficulty, contentEn, contentTr } = item.json;

  const languagesToUse = item.json.onlyLanguage ? [item.json.onlyLanguage] : ["en", "tr"];
  const languageContent = { en: contentEn, tr: contentTr };
  for (const language of languagesToUse) {
    const content = languageContent[language];
    const lineCount = content.split("\n").length;
    const computedBucket = bucketForLineCount(lineCount);
    const bucket = computedBucket.bucket;
    const count = item.json.overrideCount || computedBucket.count;
    const codeSignals = countCodeSignals(content);
    const typeMix = typeMixFor(codeSignals);
    const difficultyDistribution = difficultyDistributionFor(difficulty);
    const outlineHeadings = extractHeadings(content);
    const prompt = buildPrompt(topicSlug, language, content, outlineHeadings, count, typeMix, difficultyDistribution);

    results.push({
      json: {
        topicSlug,
        language,
        outlineHeadings,
        contentDepthBucket: bucket,
        contentLineCount: lineCount,
        codeSignals,
        targetCount: count,
        typeMix,
        difficultyDistribution,
        prompt,
      }
    });
  }
}
return results;

// Parse Generated Questions stage -- reads the OpenAI Chat Completions response shape
// ({choices: [{message: {content: "<JSON array string>"}}]}) and expands it into one
// item per generated question. The real OpenAI HTTP Request node REPLACES item.json
// with the raw API response, losing topicSlug/language -- recovered here via n8n's
// paired-item lookup against Build Generation Spec (itemMatching), not from this
// node's own input, since a plain destructure would silently read undefined.
const results = [];
const inputItems = $input.all();
for (let i = 0; i < inputItems.length; i++) {
  const item = inputItems[i];
  const source = $('Build Generation Spec').itemMatching(i).json;
  const topicSlug = source.topicSlug;
  const language = source.language;

  let generated = [];
  let parseError = null;
  try {
    const raw = item.json.choices && item.json.choices[0] && item.json.choices[0].message && item.json.choices[0].message.content;
    if (!raw) throw new Error("no message content in LLM response");
    generated = JSON.parse(raw);
    if (!Array.isArray(generated)) throw new Error("LLM output is not a JSON array");
  } catch (e) {
    parseError = e.message;
  }

  if (parseError) {
    results.push({ json: { topicSlug, language, parseError, question: null } });
    continue;
  }

  for (const q of generated) {
    results.push({ json: { topicSlug, language, ...q, parseError: null } });
  }
}
return results;

// Validate Output stage -- deterministic, STRUCTURAL ONLY, mirroring
// QuestionIngestService's own rules client-side (required fields, option count,
// correct-option-count per type, enum values, non-empty/non-duplicate option text).
// Per the user's approved clarification, this does NOT reject a question for lacking
// H2-heading vocabulary overlap -- content-fit is handled upstream by grounding the
// LLM prompt in the real lesson excerpt (see Build Generation Spec), not here.
const ALLOWED_TYPES = ["SINGLE_CHOICE", "MULTIPLE_CHOICE", "CODE_OUTPUT"];
const ALLOWED_DIFFICULTIES = ["BEGINNER", "INTERMEDIATE", "ADVANCED"];

function validate(q) {
  const reasons = [];
  if (q.parseError) { reasons.push("LLM output parse error: " + q.parseError); return reasons; }
  if (!q.question || typeof q.question !== "string" || q.question.trim().length < 10) reasons.push("question text missing or too short");
  if (!q.explanation || typeof q.explanation !== "string" || q.explanation.trim().length < 10) reasons.push("explanation missing or too short");
  if (!ALLOWED_TYPES.includes(q.type)) reasons.push("invalid type: " + q.type);
  if (!ALLOWED_DIFFICULTIES.includes(q.difficulty)) reasons.push("invalid difficulty: " + q.difficulty);
  if (!Array.isArray(q.options) || q.options.length < 2) {
    reasons.push("fewer than 2 options");
  } else {
    const correctCount = q.options.filter(o => o.correct === true).length;
    if ((q.type === "SINGLE_CHOICE" || q.type === "CODE_OUTPUT") && correctCount !== 1) reasons.push(`${q.type} requires exactly one correct option, got ${correctCount}`);
    if (q.type === "MULTIPLE_CHOICE" && correctCount < 1) reasons.push("MULTIPLE_CHOICE requires at least one correct option");
    const texts = q.options.map(o => (o.optionText || "").trim().toLowerCase());
    if (new Set(texts).size !== texts.length) reasons.push("duplicate option text within question");
    if (q.options.some(o => !o.optionText || !o.optionText.trim())) reasons.push("empty option text");
  }
  if (q.type === "CODE_OUTPUT" && (!q.codeSnippet || !q.codeSnippet.trim())) reasons.push("CODE_OUTPUT requires a codeSnippet");
  if (q.type !== "CODE_OUTPUT" && q.codeSnippet) reasons.push("codeSnippet only allowed for CODE_OUTPUT");
  return reasons;
}

return $input.all().map(item => {
  const reasons = validate(item.json);
  return { json: { ...item.json, validation: { passed: reasons.length === 0, reasons } } };
});

// Duplicate Check stage -- normalized exact-match + Jaccard word-overlap, checked
// against BOTH the real existing pool (via /api/internal/questions/existing, which is
// NOT filtered by status -- even a PENDING_REVIEW/REJECTED question counts as "already
// tried") and other items within this same batch. No vector DB, per the user's approved
// clarification. Items that already failed Validate Output are passed through untouched
// (not re-checked) so Record Results can still account for every generated item.
//
// IMPORTANT: the comparable text for a CODE_OUTPUT question is `question + codeSnippet`,
// not `question` alone -- since the prompt now requires the code to live ONLY in
// codeSnippet (see Build Generation Spec), every CODE_OUTPUT item's `question` text is
// generic ("What will be the output of the following code?"), so comparing on
// `question` alone would treat every CODE_OUTPUT question as a duplicate of every other
// one regardless of what code they actually contain (a real false-positive observed
// with a real OpenAI batch: an ordinal() question and a valueOf() question were wrongly
// flagged as duplicates of each other). The existing-pool endpoint only returns
// `question` text (no codeSnippet), so that side of the comparison is unchanged --
// acceptable since older rows still have code embedded in their stored question text.
function normalize(text) {
  return (text || "").toLowerCase().replace(/[^\w\s]/g, "").replace(/\s+/g, " ").trim();
}
function tokenSet(text) {
  return new Set(normalize(text).split(" ").filter(Boolean));
}
function jaccard(a, b) {
  const inter = [...a].filter(x => b.has(x)).length;
  const union = new Set([...a, ...b]).size;
  return union === 0 ? 0 : inter / union;
}
// A false positive was observed for real: two genuinely different CODE_OUTPUT
// questions (different method calls) were flagged as duplicates of each other
// because their codeSnippets shared a large, identical enum-declaration boilerplate
// line, which dominated the Jaccard word-overlap score even though the actual
// distinguishing content (the method call/expression under test) differed
// completely. A first fix (comparing only the last code line) was ALSO found
// insufficient for real: some snippets end in a closing brace ("}") from a
// wrapping main() method, so "last line" picked up a near-empty brace instead of
// the actual expression. Fixed by picking the last line that has meaningful
// content once braces/parens/semicolons are stripped -- this reliably lands on
// the actual statement under test regardless of trailing braces.
function comparableText(q) {
  if (!q.codeSnippet) return q.question;
  const lines = q.codeSnippet.split("\n").map(l => l.trim()).filter(Boolean);
  const meaningfulLines = lines.filter(l => l.replace(/[{}();]/g, "").trim().length > 0);
  const distinctiveLine = meaningfulLines.length > 0
    ? meaningfulLines[meaningfulLines.length - 1]
    : (lines.length > 0 ? lines[lines.length - 1] : q.codeSnippet);
  return `${q.question} ${distinctiveLine}`;
}

const JACCARD_THRESHOLD = 0.6;
const baseUrl = $env.QUESTION_INGEST_BASE_URL || "http://localhost:8080";
const apiKey = $env.QUIZ_INGEST_API_KEY;

const items = $input.all().filter(i => i.json.validation && i.json.validation.passed);
const skipped = $input.all().filter(i => !i.json.validation || !i.json.validation.passed);

const existingCache = {};
const results = [];

for (const item of items) {
  const { topicSlug, language } = item.json;
  const key = topicSlug + "::" + language;
  if (!(key in existingCache)) {
    existingCache[key] = await this.helpers.httpRequest({
      method: "GET",
      url: `${baseUrl}/api/internal/questions/existing?topicSlug=${encodeURIComponent(topicSlug)}&language=${encodeURIComponent(language)}`,
      headers: { "X-Api-Key": apiKey },
      json: true,
    });
  }

  const newText = comparableText(item.json);
  const newTokens = tokenSet(newText);
  const newNorm = normalize(newText);
  let match = null;

  for (const ex of existingCache[key]) {
    if (normalize(ex.question) === newNorm) { match = { id: ex.id, reason: "exact match (existing)" }; break; }
    const sim = jaccard(newTokens, tokenSet(ex.question));
    if (sim >= JACCARD_THRESHOLD) { match = { id: ex.id, reason: `word-overlap ${sim.toFixed(2)} (existing)` }; break; }
  }

  if (!match) {
    for (const accepted of results) {
      if (accepted.json.topicSlug !== topicSlug || accepted.json.language !== language) continue;
      const acceptedText = comparableText(accepted.json);
      const sim2 = jaccard(newTokens, tokenSet(acceptedText));
      const norm2 = normalize(acceptedText);
      if (newNorm === norm2 || sim2 >= JACCARD_THRESHOLD) { match = { id: "batch:" + acceptedText.slice(0, 30), reason: "within-batch duplicate" }; break; }
    }
  }

  results.push({ json: { ...item.json, duplicateCheck: { isDuplicate: !!match, matchedId: match ? match.id : null, reason: match ? match.reason : null } } });
}

for (const s of skipped) {
  results.push({ json: { ...s.json, duplicateCheck: { isDuplicate: false, matchedId: null, reason: "skipped (failed validation)" } } });
}

return results;

// AI Judge Prep -- eligibility check + lesson-content fetch + judge prompt build.
// Split out of the original single "AI Judge" Code node as an n8n 2.35.3 compatibility
// fix: this n8n version's JS Task Runner sandbox only exposes helpers.httpRequest /
// helpers.request to Code nodes (see @n8n/task-runner's EXPOSED_RPC_METHODS list --
// helpers.httpRequestWithAuthentication is explicitly listed in
// UNSUPPORTED_HELPER_FUNCTIONS and throws synchronously, before any network call).
// The actual authenticated OpenAI call now happens in a real HTTP Request node
// ("AI Judge Call OpenAI"), using the SAME predefinedCredentialType/openAiApi pattern
// already proven working by "Generate Batch" -- no OpenAI key is ever read, decrypted,
// or handled inside this Code node. This node only builds the prompt text (plain
// helpers.httpRequest against the app's own /api/internal/** content endpoint, same as
// before, using $env.QUIZ_INGEST_API_KEY -- unrelated to the OpenAI credential).
// Ineligible items (failed validation or duplicate) get their final judge verdict set
// directly here and are routed around the OpenAI call entirely by the next (IF) node --
// same zero-wasted-calls behavior as the original design.
const baseUrl = $env.QUESTION_INGEST_BASE_URL || "http://localhost:8080";
const apiKey = $env.QUIZ_INGEST_API_KEY;

const contentCache = {};
async function getTopicContent(topicSlug, language) {
  const key = topicSlug + "::" + language;
  if (!(key in contentCache)) {
    contentCache[key] = await this.helpers.httpRequest({
      method: "GET",
      url: `${baseUrl}/api/internal/topics/${topicSlug}/content?lang=${language}`,
      headers: { "X-Api-Key": apiKey },
    });
  }
  return contentCache[key];
}

function buildJudgePrompt(q, lessonContent) {
  const optionsText = (q.options || [])
    .map((o, i) => `${i + 1}. ${o.optionText}${o.correct ? " [marked CORRECT]" : ""}`)
    .join("\n");
  return `You are a strict, independent reviewer for a quiz question that will be shown to real learners. Judge ONLY the question below against the lesson content -- you did not write this question, treat it with skepticism.

--- LESSON CONTENT (source of truth) ---
${lessonContent}
--- END LESSON CONTENT ---

CANDIDATE QUESTION
Type: ${q.type}
Difficulty: ${q.difficulty}
Question: ${q.question}
${q.codeSnippet ? "Code/command snippet (" + (q.codeLanguage || "unspecified") + "):\n" + q.codeSnippet + "\n" : ""}Options (in order, marked options are what the generator claims are correct):
${optionsText}
Explanation given: ${q.explanation}

Check ALL of the following:
1. Factual correctness -- is everything stated or implied actually true?
2. Is the question fully answerable from the lesson content above, not from outside knowledge?
3. Are the option(s) marked CORRECT actually correct, and are the other options actually incorrect?
4. If a code/command snippet is present, is it syntactically valid and does it actually produce the claimed result (for CODE_OUTPUT, does the snippet genuinely produce one of the options as its true output)?
5. Pedagogical quality -- does this test real understanding of the topic (not trivia), is the wording clear and unambiguous, are the distractors plausible rather than absurd?

Respond with STRICT JSON ONLY, no prose, no markdown fences, exactly this shape:
{"verdict": "APPROVE", "reason": "..."} or {"verdict": "REJECT", "reason": "..."}

The reason must be one concise sentence. If you are not fully confident the question is correct and high quality, you MUST answer REJECT -- never APPROVE when in doubt.`;
}

const results = [];
for (const item of $input.all()) {
  const q = item.json;
  const eligible = q.validation && q.validation.passed && q.duplicateCheck && !q.duplicateCheck.isDuplicate;

  if (!eligible) {
    results.push({ json: { ...q, needsJudgeCall: false, judge: { verdict: null, reason: "skipped (not eligible: failed validation or duplicate)" } } });
    continue;
  }

  try {
    const lessonContent = await getTopicContent(q.topicSlug, q.language);
    const judgePrompt = buildJudgePrompt(q, lessonContent);
    results.push({ json: { ...q, needsJudgeCall: true, judgePrompt } });
  } catch (e) {
    // Could not even fetch lesson content to build the prompt -- REJECT-equivalent,
    // same fail-safe rule as a failed judge call itself. Never default-approve.
    results.push({ json: { ...q, needsJudgeCall: false, judge: { verdict: "REJECT", reason: "judge prep failed: " + e.message } } });
  }
}
return results;

// AI Judge Parse Verdict -- parses the real OpenAI response from "AI Judge Call OpenAI"
// into the final judge verdict. Same REJECT-on-any-failure fail-safe as the original
// single-node design: a malformed/missing JSON body, a missing verdict, a missing
// reason, or an HTTP-level error (the HTTP node uses onError: "continueRegularOutput",
// so a failed call surfaces as an `error` field on the item instead of throwing) all
// resolve to REJECT -- never a default APPROVE. The HTTP Request node replaces
// item.json with the raw OpenAI response, so the original question fields are recovered
// via itemMatching back to "AI Judge Prep", the same pattern already used by
// "Parse Generated Questions" (-> "Build Generation Spec") elsewhere in this workflow.
function rejectEquivalent(reason) {
  return { verdict: "REJECT", reason };
}

const results = [];
const items = $input.all();
for (let i = 0; i < items.length; i++) {
  const response = items[i].json;
  const original = $("AI Judge Prep").itemMatching(i).json;
  let judge;
  try {
    if (response && response.error) {
      throw new Error(typeof response.error === "string" ? response.error : JSON.stringify(response.error));
    }
    const raw = response && response.choices && response.choices[0] && response.choices[0].message && response.choices[0].message.content;
    if (!raw) throw new Error("no message content in judge response");
    const parsed = JSON.parse(raw);
    if (parsed.verdict !== "APPROVE" && parsed.verdict !== "REJECT") {
      throw new Error("judge returned an unrecognized verdict: " + JSON.stringify(parsed.verdict));
    }
    if (!parsed.reason || typeof parsed.reason !== "string") {
      throw new Error("judge response missing a reason string");
    }
    judge = { verdict: parsed.verdict, reason: parsed.reason };
  } catch (e) {
    judge = rejectEquivalent("judge call failed or returned invalid output: " + e.message);
  }
  const { judgePrompt, needsJudgeCall, ...rest } = original;
  results.push({ json: { ...rest, judge } });
}
return results;

// Submit Valid Questions stage -- POSTs only items that passed BOTH Validate Output
// and Duplicate Check to the EXISTING /api/internal/questions/ingest endpoint (same
// auth/no-retry pattern proven in Faz 145). source is always "OPENAI" for this workflow
// (the LLM provider actually used by Generate Batch), no status field --
// the API forces PENDING_REVIEW regardless. Items that don't qualify are passed through
// with an explicit skip reason instead of being dropped, so Record Results can still
// summarize the full batch.
const baseUrl = $env.QUESTION_INGEST_BASE_URL || "http://localhost:8080";
const apiKey = $env.QUIZ_INGEST_API_KEY;
const results = [];

for (const item of $input.all()) {
  const j = item.json;
  const submittable = j.validation && j.validation.passed && j.duplicateCheck && !j.duplicateCheck.isDuplicate;

  if (!submittable) {
    results.push({ json: { ...j, submission: { attempted: false, success: false, reason: (!j.validation || !j.validation.passed) ? "failed validation" : "duplicate" } } });
    continue;
  }

  try {
    const response = await this.helpers.httpRequest({
      method: "POST",
      url: `${baseUrl}/api/internal/questions/ingest`,
      headers: { "X-Api-Key": apiKey, "Content-Type": "application/json" },
      body: {
        topicSlug: j.topicSlug,
        language: j.language,
        type: j.type,
        difficulty: j.difficulty,
        source: "OPENAI",
        question: j.question,
        codeSnippet: j.codeSnippet || null,
        codeLanguage: j.codeLanguage || null,
        explanation: j.explanation,
        options: j.options,
      },
      json: true,
    });
    results.push({ json: { ...j, submission: { attempted: true, success: true, id: response.id, status: response.status } } });
  } catch (e) {
    results.push({ json: { ...j, submission: { attempted: true, success: false, reason: e.message } } });
  }
}
return results;

// Post-Ingest Status Decision stage -- for every question that was just successfully
// ingested (submission.success === true, still landed PENDING_REVIEW as always) AND
// received an APPROVE verdict from the AI Judge, call the new, narrow
// POST /api/internal/questions/{id}/auto-publish endpoint to move it straight to
// PUBLISHED. Everything else (REJECT verdict, judge failure, ingest failure, or the
// per-run volume cap below) is left exactly as ingest put it -- PENDING_REVIEW,
// visible on the existing human /{lang}/admin/questions review screen. A 409 here
// (already published/processed) or any other auto-publish failure does not throw --
// it is recorded and the run continues, matching Submit Valid Questions' own
// per-item try/catch convention.
//
// MAX_AUTO_PUBLISH_PER_RUN is a deliberate safety cap (per the approved plan) so a
// prompt-drift or judge-quality incident in one run cannot flood PUBLISHED --
// anything beyond the cap simply stays PENDING_REVIEW for human review.
const MAX_AUTO_PUBLISH_PER_RUN = 10;

const baseUrl = $env.QUESTION_INGEST_BASE_URL || "http://localhost:8080";
const apiKey = $env.QUIZ_INGEST_API_KEY;
const model = $env.OPENAI_MODEL || "gpt-4o-mini";
const runId = $execution.id;

let autoPublishedCount = 0;
const results = [];

for (const item of $input.all()) {
  const j = item.json;
  const ingested = j.submission && j.submission.success;
  const approved = j.judge && j.judge.verdict === "APPROVE";

  if (!ingested || !approved) {
    results.push({ json: { ...j, autoPublish: { attempted: false, success: false, reason: !ingested ? "not ingested" : "judge did not approve" } } });
    continue;
  }

  if (autoPublishedCount >= MAX_AUTO_PUBLISH_PER_RUN) {
    results.push({ json: { ...j, autoPublish: { attempted: false, success: false, reason: `auto-publish cap (${MAX_AUTO_PUBLISH_PER_RUN}) reached for this run -- left PENDING_REVIEW` } } });
    continue;
  }

  try {
    const response = await this.helpers.httpRequest({
      method: "POST",
      url: `${baseUrl}/api/internal/questions/${j.submission.id}/auto-publish`,
      headers: { "X-Api-Key": apiKey, "Content-Type": "application/json" },
      body: { runId, modelName: model, reason: j.judge.reason },
      json: true,
    });
    autoPublishedCount++;
    results.push({ json: { ...j, autoPublish: { attempted: true, success: true, status: response.status } } });
  } catch (e) {
    results.push({ json: { ...j, autoPublish: { attempted: true, success: false, reason: e.message } } });
  }
}
return results;

// Record Results stage -- final summary of the whole run (generated / validation-failed
// / deduped-out / submitted / submission-failed / judge-approved / judge-rejected /
// auto-published / auto-publish-failed counts, plus a per-question detail list),
// visible directly in n8n's own execution log. No new logging infrastructure here --
// the durable audit trail for auto-publish itself lives in the app's own
// question_publish_log table (written by QuestionReviewService.autoPublish), this is
// just the human-readable run summary.
const items = $input.all().map(i => i.json);
const summary = {
  totalGenerated: items.length,
  validationFailed: items.filter(i => !i.validation || !i.validation.passed).length,
  duplicatesSkipped: items.filter(i => i.validation && i.validation.passed && i.duplicateCheck && i.duplicateCheck.isDuplicate).length,
  submitted: items.filter(i => i.submission && i.submission.success).length,
  submissionFailed: items.filter(i => i.submission && i.submission.attempted && !i.submission.success).length,
  judgeApproved: items.filter(i => i.judge && i.judge.verdict === "APPROVE").length,
  judgeRejected: items.filter(i => i.judge && i.judge.verdict === "REJECT").length,
  autoPublished: items.filter(i => i.autoPublish && i.autoPublish.success).length,
  autoPublishFailed: items.filter(i => i.autoPublish && i.autoPublish.attempted && !i.autoPublish.success).length,
  details: items.map(i => ({
    topicSlug: i.topicSlug,
    language: i.language,
    question: i.question ? i.question.slice(0, 70) : null,
    validationPassed: i.validation ? i.validation.passed : false,
    validationReasons: i.validation ? i.validation.reasons : [],
    isDuplicate: i.duplicateCheck ? i.duplicateCheck.isDuplicate : false,
    duplicateReason: i.duplicateCheck ? i.duplicateCheck.reason : null,
    submitted: i.submission ? i.submission.success : false,
    submittedId: i.submission ? i.submission.id : null,
    judgeVerdict: i.judge ? i.judge.verdict : null,
    judgeReason: i.judge ? i.judge.reason : null,
    autoPublished: i.autoPublish ? i.autoPublish.success : false,
    autoPublishReason: i.autoPublish ? i.autoPublish.reason : null,
  })),
};
return [{ json: summary }];
